/// <summary>
///     Data Controller class for <c>AVATOSBonusEvaluationReportController</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVATOSBonusEvaluationReport</c> SSRS Report.
/// </remarks>
internal final class AVATOSBonusEvaluationReportController extends  SrsReportRunController
{
    Args            clsArgs;
    KCS_BOSTrans_B  clsKCS_BOSTrans_B;
    KCS_TOSTable    clsKCS_TOSTable;
    CustTable       clsCustTable;
    boolean         clsPreviewMode;

}

Method.Source:
    /// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVATOSBonusEvaluationReportController</c> as return value
/// </returns>
public static AVATOSBonusEvaluationReportController construct()
{
    return new AVATOSBonusEvaluationReportController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmKCS_BOSTrans_B</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>SalesTable</c> as type
/// </param>
/// <returns>
///    <c>KCS_BOSTrans_B</c> as return value
/// </returns>
public KCS_BOSTrans_B parmKCS_BOSTrans_B(KCS_BOSTrans_B _parmValue = clsKCS_BOSTrans_B)
{
    clsKCS_BOSTrans_B = _parmValue;

    return clsKCS_BOSTrans_B;
}

/// <summary>
///    AVA <c>parmKCS_TOSTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>KCS_TOSTable</c> as type
/// </param>
/// <returns>
///    <c>KCS_TOSTable</c> as return value
/// </returns>
public KCS_TOSTable parmKCS_TOSTable(KCS_TOSTable _parmValue = clsKCS_TOSTable)
{
    clsKCS_TOSTable = _parmValue;

    return clsKCS_TOSTable;
