/// <summary>
///    AVA <c>parmCustTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>CustTable</c> as type
/// </param>
/// <returns>
///    <c>CustTable</c> as return value
/// </returns>
public CustTable parmCustTable(CustTable _parmValue = clsCustTable)
{
    clsCustTable = _parmValue;

    return clsCustTable;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVATOSBonusEvaluationReportController controller;

    controller = AVATOSBonusEvaluationReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVATOSBonusEvaluationReport, Report));
    controller.parmDialogCaption("@NDX:NXABonusEvaluation");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVATOSBonusEvaluationReportContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();
    /* no default values anymore
    contract.parmCustAccount(clsCustTable.AccountNum);
    contract.parmTOSId(clsKCS_TOSTable.TOSId);
    contract.parmPrintMode(AVADetailedSummarized::Detailed);
    */
    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        /*
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVATOSBonusEvaluationReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else 
        */   
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVATOSBonusEvaluationReportAction))
        {
            clsPreviewMode = false;
        }
        /*
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVATOSBonusEvaluationReportOutput))
        {
            clsPreviewMode = false;
        }
        */
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVATOSBonusEvaluationReportController</c> as return value
/// </returns>
public static AVATOSBonusEvaluationReportController newFromArgs(Args _args)
{
    AVATOSBonusEvaluationReportController   locController;
    Common                                  locCommon;
    KCS_BOSTrans_B                          locKCS_BOSTrans_B;
    KCS_TOSTable                            locKCS_TOSTable;
    CustTable                               locCustTable;

    //locController = new AVATOSBonusEvaluationReportController();
    locController = AVATOSBonusEvaluationReportController::construct();
    locController.parmArgs(_args);
    // default for LoadFromSysLAstValue
    //locController.parmLoadFromSysLastValue(false);
    locController.parmLoadFromSysLastValue(true);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();

            switch(locCommon.TableId)
            {
                case tableNum(KCS_BOSTrans_B):
                    locKCS_BOSTrans_B = locCommon;
                    locController.parmKCS_BOSTrans_B(locKCS_BOSTrans_B);
                    if(locKCS_BOSTrans_B.TOSId)
                    {
                        locKCS_TOSTable = KCS_TOSTable::find(locKCS_BOSTrans_B.TOSId);
                        locController.parmKCS_TOSTable(locKCS_TOSTable);
                    }
                    else
                    {
                        locCustTable = CustTable::find(locKCS_BOSTrans_B.CustAccount);
                        locController.parmCustTable(locCustTable);
                    }
                    break;

                case tableNum(KCS_TOSTable):
                    locKCS_TOSTable = locCommon;
                    locController.parmKCS_TOSTable(locKCS_TOSTable);
                    break;

                case tableNum(CustTable):
                    locCustTable = locCommon;
                    locController.parmCustTable(locCustTable);
                    break;

                default:
                    locController.parmLoadFromSysLastValue(true);
            }
        }
        else
        {
            locController.parmLoadFromSysLastValue(true);
        }
    }
    return locController;
}
